// Replays Shared/Definitions/conformance/movement_vectors.txt (generated by the
// Rust implementation) and requires bit-identical results.
#include "TestFramework.h"
#include "NetCore/TfpsMap.h"
#include "NetCore/TfpsMovement.h"

#include <cstdlib>
#include <fstream>
#include <sstream>
#include <string>

namespace
{
	std::string ReadFile(const std::string& Path)
	{
		std::ifstream F(Path, std::ios::binary);
		std::stringstream SS;
		SS << F.rdbuf();
		return SS.str();
	}

	float Hex(const std::string& S) { return tfps::BitsToFloat(static_cast<uint32_t>(std::strtoul(S.c_str(), nullptr, 16))); }

	bool ReadState(std::istringstream& In, tfps::MoveState& S)
	{
		std::string V[9];
		for (auto& X : V) { if (!(In >> X)) { return false; } }
		S.Pos = tfps::Vec3(Hex(V[0]), Hex(V[1]), Hex(V[2]));
		S.Vel = tfps::Vec3(Hex(V[3]), Hex(V[4]), Hex(V[5]));
		S.bOnGround = V[6] == "1";
		S.bCrouched = V[7] == "1";
		S.JumpTimer = Hex(V[8]);
		return true;
	}
}

TFPS_TEST(MovementConformanceWithRust)
{
	const std::string Text = ReadFile(std::string(TFPS_REPO_ROOT) + "/Shared/Definitions/conformance/movement_vectors.txt");
	TFPS_REQUIRE(!Text.empty());
	std::istringstream Lines(Text);
	std::string Line;
	std::getline(Lines, Line);
	TFPS_REQUIRE(Line == "tfps-movement-vectors 1");
	tfps::CollisionWorld World;
	tfps::MoveState State;
	float Dt = 0.0f;
	std::string SeqName;
	int Steps = 0;
	int Mismatches = 0;
	int Sequences = 0;
	while (std::getline(Lines, Line))
	{
		std::istringstream In(Line);
		std::string Kind;
		In >> Kind;
		if (Kind == "box")
		{
			std::string V[6];
			for (auto& X : V) { In >> X; }
			tfps::Aabb B;
			B.Min = tfps::Vec3(Hex(V[0]), Hex(V[1]), Hex(V[2]));
			B.Max = tfps::Vec3(Hex(V[3]), Hex(V[4]), Hex(V[5]));
			World.Boxes.push_back(B);
		}
		else if (Kind == "seq")
		{
			std::string DtHex;
			In >> SeqName >> DtHex;
			Dt = Hex(DtHex);
			++Sequences;
		}
		else if (Kind == "start")
		{
			ReadState(In, State);
		}
		else if (Kind == "step")
		{
			unsigned long B = 0, Y = 0;
			long P = 0;
			In >> B >> Y >> P;
			tfps::MoveInput Input;
			Input.Buttons = static_cast<uint16_t>(B);
			Input.YawQ = static_cast<uint16_t>(Y);
			Input.PitchQ = static_cast<int16_t>(P);
			tfps::MoveState Expected;
			ReadState(In, Expected);
			tfps::Simulate(State, Input, Dt, World);
			++Steps;
			if (!(State == Expected))
			{
				if (Mismatches < 5)
				{
					std::fprintf(stderr, "  mismatch in %s step %d: got pos (%.9g %.9g %.9g) expected (%.9g %.9g %.9g)\n", SeqName.c_str(), Steps,
						State.Pos.X, State.Pos.Y, State.Pos.Z, Expected.Pos.X, Expected.Pos.Y, Expected.Pos.Z);
				}
				++Mismatches;
				State = Expected; // resync and keep checking
			}
		}
	}
	std::printf("  %d sequences, %d steps, %d mismatches\n", Sequences, Steps, Mismatches);
	TFPS_EXPECT(Sequences == 18);
	TFPS_EXPECT(Steps > 10000);
	TFPS_EXPECT(Mismatches == 0);
}

TFPS_TEST(MapJsonHashMatchesRust)
{
	const std::string Text = ReadFile(std::string(TFPS_REPO_ROOT) + "/Shared/Definitions/maps/test_arena.json");
	tfps::MapDef Map;
	std::string Err;
	TFPS_REQUIRE(tfps::ParseMapJson(Text, Map, Err));
	// Value printed by the Rust server at startup ("map_hash=...").
	const char* Expected = std::getenv("TFPS_EXPECTED_MAP_HASH");
	std::printf("  map %s: %zu solids, hash %016llx\n", Map.Name.c_str(), Map.Solids.size(), static_cast<unsigned long long>(Map.GeometryHash()));
	if (Expected != nullptr)
	{
		TFPS_EXPECT(std::strtoull(Expected, nullptr, 16) == Map.GeometryHash());
	}
	TFPS_EXPECT(Map.Solids.size() == 87);
	TFPS_EXPECT(Map.Spawns.size() == 6);
}

#include "NetCore/TfpsDeterminism.h"

TFPS_TEST(DeterminismSelfTestMatchesRust)
{
	const uint64_t H = tfps::DeterminismSelfTestHash();
	std::printf("  self-test hash %016llx (expected %016llx)\n", static_cast<unsigned long long>(H), static_cast<unsigned long long>(tfps::kExpectedSelfTestHash));
	TFPS_EXPECT(tfps::DeterminismSelfTestPasses());
}
